INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 23, 'theory', 'Quiz: threads and shared state');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 23, 0, 'Why can''t Rc<T> be passed to another thread?', '["Because Rc is too large", "Because Rc cannot be cloned", "It is possible, you only need move", "Because Rc''s counter is changed non-atomically — two threads would corrupt it; Rc is not Send"]', 3, 'The compiler checks the marker trait Send: thread::spawn requires it from the closure. For threads you use Arc, which has an atomic counter.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 23, 1, 'What happens to a Mutex lock when the guard goes out of scope?', '["Nothing: you have to call unlock", "The guard''s drop runs and the lock is released by itself", "The lock stays forever", "The thread is terminated"]', 1, 'RAII: the guard releases the mutex in Drop. You cannot forget to release the lock.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 23, 2, 'What is the main idea of split-and-merge for parallel computation?', '["All threads write to a shared variable under a mutex", "Threads process the data one after another", "Each thread processes its own piece and accumulates the result locally, then the results are combined", "The data is copied into all threads"]', 2, 'No shared writes means no waiting on a lock and no cache lines bouncing between cores; the result does not depend on the order of execution.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 23, 3, 'What does Amdahl''s law tell us?', '["That the speedup is limited by the share of sequential work", "That the speedup grows linearly with the number of cores", "That the number of threads equals the number of cores", "That a mutex is slower than an atomic"]', 0, 'If 10% of a program cannot be parallelized, it will never get more than ten times faster, no matter how many cores you add.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 23, 4, 'How do you avoid a deadlock between two mutexes?', '["Take both locks at once in any order", "Use Relaxed", "Always acquire locks in the same order in all threads", "Increase the number of threads"]', 2, 'If all threads use the same acquisition order, no wait cycle can appear. try_lock with a rollback also helps.');
